/**
 * Cloudflare Worker entry that wraps the OpenNext worker to cache resized images.
 *
 * OpenNext only marks a /_next/image response cacheable when the original image
 * is sent with an "immutable" Cache-Control. Supabase Storage sends
 * "private, no-cache", so without this wrapper every view re-downloads the
 * original from Supabase and resizes it again (~0.5 s per image).
 *
 * Uploaded files get a unique timestamp+UUID name and are never overwritten, so
 * a resized copy can safely be cached for a year at the edge and in browsers.
 */

// @ts-expect-error: generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

const SUPABASE_STORAGE =
  "https://qyfntagbyxvfxjnkbarr.supabase.co/storage/v1/object/public/";

const ONE_YEAR = "public, max-age=31536000, immutable";

interface WaitUntilContext {
  waitUntil(promise: Promise<unknown>): void;
}

// The Workers runtime provides `caches.default`; it is not in the DOM types.
const edgeCache = (caches as unknown as { default: Cache }).default;

function isCacheableImageRequest(request: Request, url: URL) {
  return (
    request.method === "GET" &&
    url.pathname === "/_next/image" &&
    (url.searchParams.get("url") ?? "").startsWith(SUPABASE_STORAGE)
  );
}

/** The image handler picks the output format from Accept, so the format is part of the key. */
function cacheKey(request: Request, url: URL) {
  const accept = request.headers.get("Accept") ?? "";
  const format = accept.includes("image/avif")
    ? "avif"
    : accept.includes("image/webp")
      ? "webp"
      : "original";

  const key = new URL(url);
  key.searchParams.set("_format", format);
  return new Request(key.toString());
}

export default {
  async fetch(request: Request, env: unknown, ctx: WaitUntilContext) {
    const url = new URL(request.url);

    if (!isCacheableImageRequest(request, url)) {
      return openNextWorker.fetch(request, env, ctx);
    }

    const key = cacheKey(request, url);
    const cached = await edgeCache.match(key);
    if (cached) return cached;

    const response: Response = await openNextWorker.fetch(request, env, ctx);
    if (!response.ok) return response;

    const cacheable = new Response(response.body, response);
    cacheable.headers.set("Cache-Control", ONE_YEAR);
    ctx.waitUntil(edgeCache.put(key, cacheable.clone()));
    return cacheable;
  },
};
